223	    /**
224	     * Known E.164 country codes whose national-number length is fixed, used to split the stored
225	     * telephone into its country code and national digits for display: Australia ({@code '61'}) and
226	     * the North American Numbering Plan ({@code '1'}). A number whose country code is not listed is
227	     * split by taking its leading digit as the (minimal) country code.
228	     */
229	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of("61", 9, "1", 10);
230	
231	    /**
232	     * The stored E.164 {@link #getTelephone() telephone} formatted for humans: the country code, a
233	     * single space, then the national digits grouped in threes from the left (e.g. the stored
234	     * {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The raw telephone itself stays in
235	     * E.164 form. Returns the stored value unchanged when it is absent or not a {@code '+'}-prefixed
236	     * digit string.
237	     *
238	     * @return the human-readable telephone, or the stored value when it cannot be formatted
239	     */
240	    public String getTelephoneDisplay() {
241	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
242	            return this.telephone;
243	        }
244	        String digits = this.telephone.substring(1);
245	        String countryCode = extractCountryCode(digits);
246	        String national = digits.substring(countryCode.length());
247	        StringBuilder display = new StringBuilder("+").append(countryCode);
248	        for (int i = 0; i < national.length(); i += 3) {
249	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
250	        }
251	        return display.toString();
252	    }
253	
254	    /**
255	     * Splits the country code off an E.164 digit string (country code followed by national digits,
256	     * without the leading {@code '+'}). A country code listed in {@link #COUNTRY_NATIONAL_LENGTH}
257	     * whose required national-number length matches the remaining digits is preferred; failing that,
258	     * the leading digit is used as the country code.
259	     *
260	     * @param digits the E.164 digits without the leading {@code '+'}
261	     * @return the country-code portion of {@code digits}
262	     */
263	    private static String extractCountryCode(String digits) {
264	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
265	            String code = entry.getKey();
266	            if (digits.startsWith(code) && digits.length() - code.length() == entry.getValue()) {
267	                return code;
268	            }
269	        }
270	        return digits.substring(0, 1);
271	    }
