297	    /**
298	     * The owner's age band, derived from the {@link #getBirthDate() birth date} as at the owner's
299	     * {@link #getRegistrationDate() registration date}: {@code 'MINOR'} when under 18, {@code 'ADULT'}
300	     * when 18 to 64, and {@code 'SENIOR'} when 65 or older. The age is the number of whole years
301	     * elapsed from the birth date to the registration date (defaulting to the server's current date
302	     * when no registration date is set yet). Returns {@code null} when no birth date was supplied.
303	     *
304	     * @return the age band, or {@code null} when the birth date is absent
305	     */
306	    public String getAgeBand() {
307	        if (this.birthDate == null) {
308	            return null;
309	        }
310	        LocalDate asAt = this.registrationDate != null ? this.registrationDate : LocalDate.now();
311	        int years = Period.between(this.birthDate, asAt).getYears();
312	        if (years < 18) {
313	            return "MINOR";
314	        }
315	        if (years < 65) {
316	            return "ADULT";
317	        }
318	        return "SENIOR";
319	    }
