329	    /**
330	     * The owner's fiscal year, formatted {@code 'FY<YY>'} where {@code YY} is the two fiscal-year
331	     * digits of the owner's {@link #getMemberId() member id} (its {@code FY} segment, the two
332	     * characters following the leading region). The fiscal year starts on 1 July and is named by the
333	     * calendar year in which it ends, so a registration date on or after 1 July belongs to the
334	     * following calendar year's fiscal year (e.g. {@code 2026-07-01} is {@code 'FY27'}) while an
335	     * earlier date stays in the current one (e.g. {@code 2026-06-15} is {@code 'FY26'}). Before the
336	     * member id has been assigned it falls back to the fiscal year of the
337	     * {@link #getRegistrationDate() business-day-adjusted registration date}. Returns {@code null}
338	     * when neither a member id nor a registration date is available.
339	     *
340	     * @return the fiscal year, or {@code null} when it cannot be derived
341	     */
342	    public String getFiscalYear() {
343	        if (this.memberId != null) {
344	            String region = leadingRegion(this.memberId);
345	            if (this.memberId.length() >= region.length() + 2) {
346	                return "FY" + this.memberId.substring(region.length(), region.length() + 2);
347	            }
348	        }
349	        if (this.registrationDate == null) {
350	            return null;
351	        }
352	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
353	    }
354	
355	    /**
356	     * The fiscal year a date falls in, as a full calendar year. The fiscal year starts on 1 July and
357	     * is named by the calendar year in which it ends: a date in July through December belongs to the
358	     * next calendar year's fiscal year, while January through June stays in the current one.
359	     *
360	     * @param date the date to classify
361	     * @return the fiscal year as a four-digit calendar year
362	     */
363	    private static int fiscalYearOf(LocalDate date) {
364	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
365	    }
366	
367	    /**
368	     * The single Luhn check digit (0-9) computed over the digits contained in the given value.
369	     * Non-digit characters (such as the letter region and hex characters) are ignored. This is the
370	     * {@code CHK} segment of the {@link #getMemberId() member id}, computed over the digits of its
371	     * {@code <REGION><FY><HASH8>} prefix.
372	     *
373	     * @param value the value whose digits the check digit is computed over
374	     * @return the Luhn check digit
375	     */
376	    private static int luhnCheckDigit(String value) {
377	        int sum = 0;
378	        boolean dbl = true;
379	        for (int i = value.length() - 1; i >= 0; i--) {
380	            char c = value.charAt(i);
381	            if (c < '0' || c > '9') {
382	                continue;
383	            }
384	            int d = c - '0';
385	            if (dbl) {
386	                d *= 2;
387	                if (d > 9) {
388	                    d -= 9;
389	                }
390	            }
391	            sum += d;
392	            dbl = !dbl;
393	        }
394	        return (10 - (sum % 10)) % 10;
395	    }
396	
397	    /**
398	     * The owner's membership points, the score the {@link #getMembershipLevel() membership level} is
399	     * derived from. The score starts at 0 and gains: 2 when an email address is present, 1 when the
400	     * owner has no namesakes ({@code namesakeCount} is 0), 2 for a household of 3 or more members
401	     * ({@code householdSize} is at least 3), and 3 when the owner's tenure spans at least one elapsed
402	     * fiscal year (see {@link #getTenureFiscalYears()}). Because a newly created owner has zero
403	     * tenure, the tenure points are never awarded at create time.
404	     *
405	     * @return the membership points, a non-negative integer
406	     */
407	    public Integer getMembershipPoints() {
408	        int points = 0;
409	        boolean hasEmail = this.email != null && !this.email.isBlank();
410	        if (hasEmail) {
411	            points += 2;
412	        }
413	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
414	        if (hasNoNamesakes) {
415	            points += 1;
416	        }
417	        if (this.householdSize != null && this.householdSize >= 3) {
418	            points += 2;
419	        }
420	        Long tenureFiscalYears = getTenureFiscalYears();
421	        if (tenureFiscalYears != null && tenureFiscalYears >= 1) {
422	            points += 3;
423	        }
424	        return points;
425	    }
426	
427	    /**
428	     * The owner's numeric membership level. This is normally derived from the
429	     * {@link #getMembershipPoints() membership points} (see {@link #deriveMembershipLevel()}), but a
430	     * household-level cap applied at create time may store a lower value here; when such a capped level
431	     * has been stored it is returned in preference to the derived one.
432	     *
433	     * @return the membership level, an integer from 1 to 4
434	     */
435	    public Integer getMembershipLevel() {
436	        if (this.membershipLevel != null) {
437	            return this.membershipLevel;
438	        }
439	        return deriveMembershipLevel();
440	    }
441	
442	    public void setMembershipLevel(Integer membershipLevel) {
443	        this.membershipLevel = membershipLevel;
444	    }
445	
446	    /**
447	     * The owner's numeric membership level derived purely from the {@link #getMembershipPoints()
448	     * membership points}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and
449	     * level 4 for 6 or more points. This is the uncapped level, before any household-level cap.
450	     *
451	     * @return the derived membership level, an integer from 1 to 4
452	     */
453	    public Integer deriveMembershipLevel() {
454	        int points = getMembershipPoints();
455	        if (points <= 1) {
456	            return 1;
457	        }
458	        if (points <= 3) {
459	            return 2;
460	        }
461	        if (points <= 5) {
462	            return 3;
463	        }
464	        return 4;
465	    }
466	
467	    /**
468	     * The owner's tenure in elapsed fiscal years, the number of fiscal-year boundaries crossed from
469	     * the {@link #getFiscalYear() fiscal year} of the {@link #getRegistrationDate() registration date}
470	     * to the fiscal year of the server's current date (the fiscal year starts on 1 July). An owner
471	     * registered in the current fiscal year has a tenure of 0; one elapsed fiscal year or more is what
472	     * awards the tenure membership points. Returns {@code null} when no registration date has been set
473	     * yet.
474	     *
475	     * @return the tenure in elapsed fiscal years, or {@code null} when the registration date is absent
476	     */
477	    public Long getTenureFiscalYears() {
478	        if (this.registrationDate == null) {
479	            return null;
480	        }
481	        return (long) (fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate));
482	    }
483	
484	    /**
485	     * The owner's locality, the canonical region string. Once the owner has a
486	     * {@link #getMemberId() member id} the locality is the {@code <REGION>} component of that id (its
487	     * leading run of letters, before the fiscal-year digits), so the locality and the identity share a
488	     * single source of truth. Before the member id is assigned (for example while a create is still
489	     * validating the postcode) it falls back to the region the id will be built from: the
490	     * {@link #getPostcode() postcode} looked up by range first (NSW 2000-2099, VIC 3000-3099,
491	     * QLD 4000-4099), then the fixed city-to-region table (Sydney->NSW, Melbourne->VIC,
492	     * Brisbane->QLD), and finally {@code 'UNKNOWN'} when neither resolves to a region.
493	     *
494	     * @return the canonical region string, or {@code 'UNKNOWN'}
495	     */
496	    public String getLocality() {
497	        if (this.memberId != null) {
498	            return leadingRegion(this.memberId);
499	        }
500	        return deriveRegion();
501	    }
502	
503	    /**
504	     * The leading region component of a {@link #getMemberId() member id}: its leading run of letters,
505	     * which ends at the first fiscal-year digit. The member id has no separators, so the region is the
506	     * alphabetic prefix (e.g. {@code 'NSW'} or {@code 'UNKNOWN'}) that precedes the {@code <FY>} digits.
507	     *
508	     * @param memberId the member id to read the region from
509	     * @return the leading region string
510	     */
511	    private static String leadingRegion(String memberId) {
512	        int end = 0;
513	        while (end < memberId.length() && Character.isLetter(memberId.charAt(end))) {
514	            end++;
515	        }
516	        return memberId.substring(0, end);
517	    }
518	
519	    /**
520	     * The owner's IANA timezone name, derived from the owner's {@link #getLocality() locality} via the
521	     * fixed region-to-timezone table: NSW->Australia/Sydney, VIC->Australia/Melbourne,
522	     * QLD->Australia/Brisbane. Returns {@code null} when the locality is not one of these regions (for
523	     * example the {@code 'UNKNOWN'} locality of a city with no known region).
524	     *
525	     * @return the IANA timezone name, or {@code null} when the locality has no mapped timezone
526	     */
527	    public String getTimezone() {
528	        return REGION_TIMEZONE.get(getLocality());
529	    }
530	
531	    /**
532	     * The owner's segment, formatted {@code '<TIER>_<AREA>'}, one of {@code 'PREMIUM_METRO'},
533	     * {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or {@code 'STANDARD_REGIONAL'}. {@code TIER}
534	     * is {@code 'PREMIUM'} when the {@link #getMembershipLevel() membership level} is 3 or more,
535	     * otherwise {@code 'STANDARD'}. {@code AREA} is {@code 'METRO'} when the {@link #getLocality()
536	     * locality} is a known region (NSW, VIC or QLD), otherwise {@code 'REGIONAL'}.
537	     *
538	     * @return the owner segment string
539	     */
540	    public String getOwnerSegment() {
541	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
542	        String area = REGION_TIMEZONE.containsKey(getLocality()) ? "METRO" : "REGIONAL";
543	        return tier + "_" + area;
544	    }
545	
546	    /**
547	     * The region the customer code's {@code <REGION>} component is built from: the postcode looked up
548	     * by range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), falling back to the fixed
549	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or
550	     * in no known range, and {@code 'UNKNOWN'} when neither resolves. Preferring the postcode returns
551	     * the same region for known cities but disambiguates cities that share a name.
552	     *
553	     * @return the canonical region string, or {@code 'UNKNOWN'}
554	     */
555	    private String deriveRegion() {
556	        String region = regionFromPostcode();
557	        if (region != null) {
558	            return region;
559	        }
560	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
561	    }
562	
563	    /**
564	     * Builds this owner's member id, formatted {@code '<REGION><FY><HASH8><CHK>'}. {@code REGION} is
565	     * the region derived from the postcode (falling back to the city, then {@code 'UNKNOWN'}; see
566	     * {@link #deriveRegion()}); {@code FY} is the two-digit fiscal year of the
567	     * {@link #getRegistrationDate() registration date} (the fiscal year starts on 1 July; see
568	     * {@link #fiscalYearOf(LocalDate)}); {@code HASH8} is the first 8 upper-case hexadecimal
569	     * characters of the SHA-256 digest of the owner's normalized telephone concatenated with its last
570	     * name (the same hash the region-and-hash identity uses); and {@code CHK} is a single Luhn check
571	     * digit over the digits of the {@code <REGION><FY><HASH8>} prefix (e.g. {@code 'NSW261A2B3C4D7'}).
572	     * It carries no sequence number, so it is a pure function of the owner's region, fiscal year,
573	     * telephone and last name. Call this once at create time and store the result via
574	     * {@link #setMemberId(String)}, which thereafter backs {@link #getLocality()} and
575	     * {@link #getFiscalYear()}.
576	     *
577	     * @return the assembled member id
578	     */
579	    public String buildMemberId() {
580	        String base = deriveRegion()
581	            + String.format("%02d", fiscalYearOf(this.registrationDate) % 100)
582	            + sha256Hex8(this.telephone + this.getLastName());
583	        return base + luhnCheckDigit(base);
584	    }
585	
586	    /**
587	     * Computes the first 8 upper-case hexadecimal characters (the first 4 bytes) of the SHA-256 digest
588	     * of the given value's UTF-8 bytes, the {@code HASH8} component of the customer code.
589	     *
590	     * @param value the value to hash
591	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
592	     */
593	    private static String sha256Hex8(String value) {
594	        try {
595	            byte[] digest = MessageDigest.getInstance("SHA-256")
596	                .digest(value.getBytes(StandardCharsets.UTF_8));
597	            StringBuilder hex = new StringBuilder(8);
598	            for (int i = 0; i < 4; i++) {
599	                hex.append(String.format("%02X", digest[i]));
600	            }
601	            return hex.toString();
602	        }
603	        catch (NoSuchAlgorithmException e) {
604	            throw new IllegalStateException("SHA-256 algorithm not available", e);
605	        }
606	    }
607	
608	    /**
609	     * The region whose range contains this owner's postcode, or {@code null} when the postcode is
610	     * absent, not a 4-digit number, or in no known range.
611	     *
612	     * @return the matching region, or {@code null}
613	     */
614	    private String regionFromPostcode() {
615	        if (this.postcode == null) {
616	            return null;
617	        }
618	        int value;
619	        try {
620	            value = Integer.parseInt(this.postcode.trim());
621	        }
622	        catch (NumberFormatException ex) {
623	            return null;
624	        }
625	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE.entrySet()) {
626	            int[] range = entry.getValue();
627	            if (value >= range[0] && value <= range[1]) {
628	                return entry.getKey();
629	            }
630	        }
631	        return null;
632	    }
633	
634	    /**
635	     * The owner's preferred contact channel, derived from the owner's details. Returns
636	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
637	     *
638	     * @return {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}
639	     */
640	    public String getContactPreference() {
641	        boolean hasEmail = this.email != null && !this.email.isBlank();
642	        return hasEmail ? "EMAIL" : "PHONE";
643	    }
644	
645	    /**
646	     * The owner's identity key, the single derived value used for duplicate detection. It is the
647	     * lower-case SHA-256 hex digest (64 characters) of the owner's normalized telephone, lower-cased
648	     * email (empty when absent) and the {@linkplain Soundex#encode(String) Soundex} of its last name,
649	     * joined with {@code '|'} ({@code sha256hex('<telephone>|<lowerEmail>|<soundex(lastName)>')}); any
650	     * absent ({@code null}) component contributes an empty string before hashing. Two owners are
651	     * duplicates exactly when their whole identity keys are equal, so two owners sharing a last name
652	     * (and its Soundex) and postcode but carrying different telephones differ here and are both
653	     * allowed (the second is flagged a soft match rather than rejected).
654	     *
655	     * @return the derived identity key, a 64-character lower-case hex string
656	     */
657	    public String getIdentityKey() {
658	        String normalizedTelephone = this.telephone == null ? "" : this.telephone;
659	        String lowerEmail = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
660	        String raw = normalizedTelephone + "|" + lowerEmail + "|" + Soundex.encode(this.getLastName());
661	        return sha256HexLower(raw);
662	    }
663	
664	    /**
665	     * The full lower-case SHA-256 hex digest (64 characters) of the given value's UTF-8 bytes, the
666	     * form the {@linkplain #getIdentityKey() identity key} takes.
667	     *
668	     * @param value the value to hash
669	     * @return the 64-character lower-case hex SHA-256 digest
670	     */
671	    private static String sha256HexLower(String value) {
672	        try {
673	            byte[] digest = MessageDigest.getInstance("SHA-256")
674	                .digest(value.getBytes(StandardCharsets.UTF_8));
675	            StringBuilder hex = new StringBuilder(digest.length * 2);
676	            for (byte b : digest) {
677	                hex.append(String.format("%02x", b));
678	            }
679	            return hex.toString();
680	        }
681	        catch (NoSuchAlgorithmException e) {
682	            throw new IllegalStateException("SHA-256 algorithm not available", e);
683	        }
684	    }
