747	        this.possibleDuplicateOf = possibleDuplicateOf;
748	    }
749	
750	    /**
751	     * A consolidated risk indicator for the owner, derived from its other attributes. It is
752	     * {@code true} when any of the following hold, and {@code false} otherwise:
753	     * <ul>
754	     *   <li>the owner is a possible duplicate ({@link #getPossibleDuplicate() possibleDuplicate});</li>
755	     *   <li>its email domain is disposable-adjacent (see {@link #isDisposableAdjacentEmail()});</li>
756	     *   <li>its city is over its soft capacity ({@link #getCapacityWarning() capacityWarning}, the city
757	     *       already held 40 or more owners when this owner was created).</li>
758	     * </ul>
759	     *
760	     * @return whether the owner carries any of the risk conditions
761	     */
762	    public Boolean getRiskFlag() {
763	        return Boolean.TRUE.equals(this.possibleDuplicate)
764	            || Boolean.TRUE.equals(this.capacityWarning)
765	            || isDisposableAdjacentEmail();
766	    }
767	
768	    /**
769	     * Whether the owner's email domain is <em>disposable-adjacent</em>: it shares the second-level name
770	     * of a known disposable mail provider ({@link #DISPOSABLE_EMAIL_DOMAINS}) without necessarily being
771	     * an exact match. This catches the common evasions of the exact-match create-time block - a subdomain
772	     * of a disposable provider (e.g. {@code mail.mailinator.com}) and a sibling top-level domain of one
773	     * (e.g. {@code mailinator.net}) - both of which resolve to the same second-level label
774	     * (e.g. {@code mailinator}). The comparison is case-insensitive. An absent or malformed email is not
775	     * disposable-adjacent.
776	     *
777	     * @return whether the owner's email domain is adjacent to a known disposable provider
778	     */
779	    private boolean isDisposableAdjacentEmail() {
780	        if (this.email == null || this.email.isBlank()) {
781	            return false;
782	        }
783	        int at = this.email.lastIndexOf('@');
784	        if (at < 0 || at == this.email.length() - 1) {
785	            return false;
786	        }
787	        String base = secondLevelLabel(this.email.substring(at + 1).toLowerCase(Locale.ROOT));
788	        if (base.isEmpty()) {
789	            return false;
790	        }
791	        for (String disposable : DISPOSABLE_EMAIL_DOMAINS) {
792	            if (base.equals(secondLevelLabel(disposable))) {
793	                return true;
794	            }
795	        }
796	        return false;
797	    }
798	
799	    /**
800	     * The second-level label of a dot-separated domain - the label immediately before the final one
801	     * (e.g. {@code mailinator} for {@code mailinator.com}, {@code mail.mailinator.com} and
802	     * {@code mailinator.net} alike). A domain with no dot is returned unchanged.
803	     *
804	     * @param domain the lower-cased domain to inspect
805	     * @return the second-level label
806	     */
807	    private static String secondLevelLabel(String domain) {
808	        String[] labels = domain.split("\\.");
809	        if (labels.length < 2) {
810	            return domain;
811	        }
812	        return labels[labels.length - 2];
813	    }
814	
815	    /**
816	     * Whether this owner has been soft-deleted. A newly created owner is not deleted
817	     * ({@code false}); the DELETE endpoint marks the owner deleted ({@code true}) while retaining the
818	     * row, and the create endpoint's duplicate and identity checks ignore owners flagged deleted.
819	     *
820	     * @return whether the owner has been soft-deleted
821	     */
822	    public boolean isDeleted() {
823	        return this.deleted;
824	    }
825	
826	    public void setDeleted(boolean deleted) {
827	        this.deleted = deleted;
828	    }
829	
830	    /**
831	     * Stamps the effective registration date exactly once on insert, so every newly persisted owner
832	     * carries a resolved, business-day registration date (see {@link #resolveRegistrationDate}).
833	     */
834	    @PrePersist
835	    void onCreate() {
836	        this.registrationDate = resolveRegistrationDate(this.registrationDate);
837	    }
838	
839	    /**
840	     * Resolves the effective registration date and rolls it onto a business day. An absent
841	     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
842	     * The resulting date is then rolled forward so it never falls on a weekend or a listed public
843	     * holiday: starting from the effective date, the date advances one day at a time while it lands
844	     * on a Saturday, a Sunday, or a date in {@link #PUBLIC_HOLIDAYS}, stopping on the first
845	     * non-holiday business day. A date already on a business day is returned unchanged.
846	     *
847	     * <p>This is the single definition of both the defaulting and the business-day roll, used
848	     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
849	     * stamps the owner and by the create endpoint that counts owners per business day.
850	     *
851	     * @param supplied the registration date from the request, or {@code null} when none was supplied
852	     * @return the effective registration date, guaranteed to fall on a non-holiday business day
853	     */
854	    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
855	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
856	        while (!isBusinessDay(effective)) {
857	            effective = effective.plusDays(1);
858	        }
859	        return effective;
860	    }
861	
862	    /**
863	     * The fixed list of public holidays that the registration date rolls past, alongside weekends.
864	     */
865	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
866	        LocalDate.of(2026, 1, 1),
867	        LocalDate.of(2026, 1, 26),
868	        LocalDate.of(2026, 4, 25),
869	        LocalDate.of(2026, 12, 25),
870	        LocalDate.of(2026, 12, 28));
871	
872	    /**
873	     * A business day is any date that is neither a weekend day nor a listed public holiday.
874	     */
875	    private static boolean isBusinessDay(LocalDate date) {
876	        DayOfWeek day = date.getDayOfWeek();
877	        return day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY && !PUBLIC_HOLIDAYS.contains(date);
878	    }
879	
880	    protected Set<Pet> getPetsInternal() {
881	        if (this.pets == null) {
882	            this.pets = new HashSet<>();
883	        }
884	        return this.pets;
885	    }
886	
887	    protected void setPetsInternal(Set<Pet> pets) {
888	        this.pets = pets;
889	    }
890	
891	    public List<Pet> getPets() {
892	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
893	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
894	        return Collections.unmodifiableList(sortedPets);
895	    }
896	
897	    public void setPets(List<Pet> pets) {
898	        this.pets = new HashSet<>(pets);
899	    }
900	
901	    public void addPet(Pet pet) {
902	        getPetsInternal().add(pet);
903	        pet.setOwner(this);
904	    }
905	
906	    /**
907	     * Return the Pet with the given name, or null if none found for this Owner.
908	     *
909	     * @param name to test
910	     * @return true if pet name is already in use
911	     */
912	    public Pet getPet(String name) {
913	        return getPet(name, false);
914	    }
915	
916	    /**
917	     * Return the Pet with the given name, or null if none found for this Owner.
918	     *
919	     * @param name to test
920	     * @return true if pet name is already in use
921	     */
922	    public Pet getPet(String name, boolean ignoreNew) {
923	        name = name.toLowerCase();
924	        for (Pet pet : getPetsInternal()) {
925	            if (!ignoreNew || !pet.isNew()) {
926	                String compName = pet.getName();
927	                compName = compName.toLowerCase();
928	                if (compName.equals(name)) {
929	                    return pet;
930	                }
931	            }
932	        }
933	        return null;
934	    }
935	
936	    public Pet getPet(Integer petId) {
937	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
938	    }
939	
940	    @Override
941	    public String toString() {
942	        return new ToStringCreator(this)
943	
944	            .append("id", this.getId())
945	            .append("new", this.isNew())
946	            .append("lastName", this.getLastName())
947	            .append("firstName", this.getFirstName())
948	            .append("address", this.address)
949	            .append("city", this.city)
950	            .append("telephone", this.telephone)
951	            .toString();
952	    }
953	}
